/** New synthetic mock reply, not a rewrite of historical malformed captures or user plans. */
export function policyAdmissibleCorrection<T>(value:T):T{const copy=structuredClone(value)as any;for(const test of copy.cases){for(const step of test.steps)if(['save_count','expect_count'].includes(step.op))step.target={by:'role',role:'article',name:'Fixture item',exact:true};for(let i=test.steps.length-1;i>1;i--){const step=test.steps[i];if(step.op==='expect_visible'&&step.visible===true&&test.steps.slice(1,i).some((s:any)=>['click','fill','press','drag_by','check'].includes(s.op))){test.steps.splice(i,1);test.steps.splice(1,0,step);}}}return copy;}
